// fmtProcessedAtIfRecorded 展示处理时间，缺失（nil）或旧数据零值
// （0001-01-01T00:00:00Z）时明确标为未记录，不推测补齐。
func fmtProcessedAtIfRecorded(t *time.Time) string {
	if t == nil || t.IsZero() {
		return "未记录"
	}
	return fmtTime(*t)
}

